          if(cont) f6_f(re+q, im+q, 8, cre+q, cim+q, sr0?sr0+q:0, si0?si0+q:0);
          else     f6_m(re+q, im+q, 8, cre+q, cim+q, sr0?sr0+q:0, si0?si0+q:0);
