static void run_6(long B, long m, const double *x0, const double *cc, double *out_one, double *out_final){
  long v = 0;
#if 1
  while(B - v >= 5){
    int nv = (B - v >= 8) ? 8 : (int)(B - v);
    convB8_in(x0 + 2*v*216L, nv, 216L, 6, 56L, 344L, bre, bim);
    if(m >= 1)
      for(int x = 0; x < 6; x++){
        long p = (long)x*344L;
        for(int y = 0; y < 6; y++) f6_p(bre + p + y*56L, bim + p + y*56L, 8);
        for(int z = 0; z < 6; z++) f6_p(bre + p + z*8, bim + p + z*8, 56L);
      }
    convB8_in(cc + 2*v*216L, nv, 216L, 6, 56L, 344L, bcr, bci);
    if(m >= 1) iterB8_6(bre, bim, bcr, bci, bsr, bsi, m, 2);
    else { memcpy(bsr, bre, sizeof(double)*6*344L); memcpy(bsi, bim, sizeof(double)*6*344L); }
    convB8_out(out_one + 2*v*216L, nv, 216L, 6, 56L, 344L, bsr, bsi);
    convB8_out(out_final + 2*v*216L, nv, 216L, 6, 56L, 344L, bre, bim);
    v += nv;
  }
#endif
  for(; v < B; v++){
    const double *sx = x0 + 2*v*216L;
    const double *sc = cc + 2*v*216L;
    for(int x = 0; x < 6; x++){
      for(int y = 0; y < 6; y++){
        long row = (long)(x*6 + y)*6;
        long d = (long)x*56 + (long)y*8;
        deint_row(sx + 2*row, bre + d, bim + d, 6, 8);
      }
      if(m >= 1){
        long p = (long)x*56;
        zpass_6(bre + p, bim + p);
        for(int zc = 0; zc < 1; zc++)
          f6_p(bre + p + zc*8, bim + p + zc*8, 8);
      }
    }
    for(int x = 0; x < 6; x++){
      for(int y = 0; y < 6; y++){
        long row = (long)(x*6 + y)*6;
        long d = (long)x*56 + (long)y*8;
        deint_row(sc + 2*row, bcr + d, bci + d, 6, 8);
      }
      for(int t = 0; t < 1; t++){
        long src_b = (long)x*56 + (long)(8*t)*8;
        long dst_b = (long)x*64 + (long)t*8*8;
        for(int jb = 0; jb < 1; jb++){
          tr8x8_ld(bcr + src_b + jb*8, 8, bctr + dst_b + jb*64);
          tr8x8_ld(bci + src_b + jb*8, 8, bcti + dst_b + jb*64);
        }
      }
    }
    if(m >= 1) iter_6(bre, bim, bcr, bci, bctr, bcti, bsr, bsi, m, 2);
    else { memcpy(bsr, bre, sizeof(double)*6*56); memcpy(bsi, bim, sizeof(double)*6*56); }
    double *d1 = out_one + 2*v*216L, *d2 = out_final + 2*v*216L;
    for(int x = 0; x < 6; x++)
      for(int y = 0; y < 6; y++){
        long row = (long)(x*6 + y)*6;
        long d = (long)x*56 + (long)y*8;
        int_row(d1 + 2*row, bsr + d, bsi + d, 6);
        int_row(d2 + 2*row, bre + d, bim + d, 6);
      }
  }
}


