static void run_45(long B, long m, const double *x0, const double *cc, double *out_one, double *out_final){
  long v = 0;
#if 0
  while(B - v >= 8){
    int nv = (B - v >= 8) ? 8 : (int)(B - v);
    convB8_in(x0 + 2*v*91125L, nv, 91125L, 45, 368L, 16568L, bre, bim);
    if(m >= 1)
      for(int x = 0; x < 45; x++){
        long p = (long)x*16568L;
        for(int y = 0; y < 45; y++) f45_p(bre + p + y*368L, bim + p + y*368L, 8);
        for(int z = 0; z < 45; z++) f45_p(bre + p + z*8, bim + p + z*8, 368L);
      }
    convB8_in(cc + 2*v*91125L, nv, 91125L, 45, 368L, 16568L, bcr, bci);
    if(m >= 1) iterB8_45(bre, bim, bcr, bci, bsr, bsi, m, 2);
    else { memcpy(bsr, bre, sizeof(double)*45*16568L); memcpy(bsi, bim, sizeof(double)*45*16568L); }
    convB8_out(out_one + 2*v*91125L, nv, 91125L, 45, 368L, 16568L, bsr, bsi);
    convB8_out(out_final + 2*v*91125L, nv, 91125L, 45, 368L, 16568L, bre, bim);
    v += nv;
  }
#endif
  for(; v < B; v++){
    const double *sx = x0 + 2*v*91125L;
    const double *sc = cc + 2*v*91125L;
    for(int x = 0; x < 45; x++){
      for(int y = 0; y < 45; y++){
        long row = (long)(x*45 + y)*45;
        long d = (long)x*2168 + (long)y*48;
        deint_row(sx + 2*row, bre + d, bim + d, 45, 48);
      }
      if(m >= 1){
        long p = (long)x*2168;
        zpass_45(bre + p, bim + p);
        for(int zc = 0; zc < 6; zc++)
          f45_p(bre + p + zc*8, bim + p + zc*8, 48);
      }
    }
    for(int x = 0; x < 45; x++){
      for(int y = 0; y < 45; y++){
        long row = (long)(x*45 + y)*45;
        long d = (long)x*2168 + (long)y*48;
        deint_row(sc + 2*row, bcr + d, bci + d, 45, 48);
      }
      for(int t = 0; t < 6; t++){
        long src_b = (long)x*2168 + (long)(8*t)*48;
        long dst_b = (long)x*2304 + (long)t*48*8;
        for(int jb = 0; jb < 6; jb++){
          tr8x8_ld(bcr + src_b + jb*8, 48, bctr + dst_b + jb*64);
          tr8x8_ld(bci + src_b + jb*8, 48, bcti + dst_b + jb*64);
        }
      }
    }
    if(m >= 1) iter_45(bre, bim, bcr, bci, bctr, bcti, bsr, bsi, m, 2);
    else { memcpy(bsr, bre, sizeof(double)*45*2168); memcpy(bsi, bim, sizeof(double)*45*2168); }
    double *d1 = out_one + 2*v*91125L, *d2 = out_final + 2*v*91125L;
    for(int x = 0; x < 45; x++)
      for(int y = 0; y < 45; y++){
        long row = (long)(x*45 + y)*45;
        long d = (long)x*2168 + (long)y*48;
        int_row(d1 + 2*row, bsr + d, bsi + d, 45);
        int_row(d2 + 2*row, bre + d, bim + d, 45);
      }
  }
}


/* ================= driver for L=64 ================= */
static void zpass_64(double *restrict pr, double *restrict pi){
  for(int y0 = 0; y0 < 64; y0 += 8){
    int rows = 64 - y0; if(rows > 8) rows = 8;
    for(int jb = 0; jb < 8; jb++){
      tr8x8_ld(pr + (long)y0*64 + jb*8, 64, ZSR + jb*64);
      tr8x8_ld(pi + (long)y0*64 + jb*8, 64, ZSI + jb*64);
    }
#if 64 > 64
    for(int j = 64; j < 64; j++){
      VS(ZSR + j*8, VK(0.0));
      VS(ZSI + j*8, VK(0.0));
    }
#endif
    f64_p(ZSR, ZSI, 8);
    for(int jb = 0; jb < 8; jb++){
      tr8x8_st(pr + (long)y0*64 + jb*8, 64, ZSR + jb*64, rows);
      tr8x8_st(pi + (long)y0*64 + jb*8, 64, ZSI + jb*64, rows);
    }
  }
}

static void zpassm_64(double *restrict pr, double *restrict pi,
                       const double *restrict ctr, const double *restrict cti, int cont){
  double *restrict ZSR_p = ZSR; double *restrict ZSI_p = ZSI;
  for(int y0 = 0; y0 < 64; y0 += 8){
    int rows = 64 - y0; if(rows > 8) rows = 8;
    const double *cr = ctr + (long)(y0/8)*64*8;
    const double *ci = cti + (long)(y0/8)*64*8;
    for(int jb = 0; jb < 8; jb++){
      tr8x8_ld(pr + (long)y0*64 + jb*8, 64, ZSR_p + jb*64);
      tr8x8_ld(pi + (long)y0*64 + jb*8, 64, ZSI_p + jb*64);
    }
#if 64 > 64
    for(int j = 64; j < 64; j++){
      VS(ZSR_p + j*8, VK(0.0));
      VS(ZSI_p + j*8, VK(0.0));
    }
#endif
    if(cont) f64_f(ZSR_p, ZSI_p, 8, cr, ci, 0, 0);
    else     f64_m(ZSR_p, ZSI_p, 8, cr, ci, 0, 0);
    for(int jb = 0; jb < 8; jb++){
      tr8x8_st(pr + (long)y0*64 + jb*8, 64, ZSR_p + jb*64, rows);
      tr8x8_st(pi + (long)y0*64 + jb*8, 64, ZSI_p + jb*64, rows);
    }
  }
}

