#define MAXV 262208

static void init_tw(void){
  for(int k2 = 1; k2 < 8; k2++)
    for(int t = 1; t < 8; t++){
      double ang = -2*3.14159265358979323846264338328/64.0 * (double)(k2*t);
      double c = __builtin_cos(ang), s = __builtin_sin(ang);
      for(int l = 0; l < 8; l++){ TWR_64[(k2-1)*7 + (t-1)][l] = c; TWI_64[(k2-1)*7 + (t-1)][l] = s; }
    }
  for(int k2 = 1; k2 < 6; k2++)
    for(int t = 1; t < 6; t++){
      double ang = -2*3.14159265358979323846264338328/36.0 * (double)(k2*t);
      double c = __builtin_cos(ang), s = __builtin_sin(ang);
      for(int l = 0; l < 8; l++){ TWR_36[(k2-1)*5 + (t-1)][l] = c; TWI_36[(k2-1)*5 + (t-1)][l] = s; }
    }
}
__attribute__((constructor)) static void init_all(void){
  init_tw();
  bre = alloc_buf(383968); bim = alloc_buf(383968);
  bcr = alloc_buf(383968); bci = alloc_buf(383968);
  bsr = alloc_buf(383968); bsi = alloc_buf(383968);
  bctr = alloc_buf(MAXV); bcti = alloc_buf(MAXV);
}
void run_size(long L, long B, long m, const double *x0, const double *cc, double *out_one, double *out_final){
  switch(L){
    case 6: run_6(B, m, x0, cc, out_one, out_final); break;
    case 8: run_8(B, m, x0, cc, out_one, out_final); break;
    case 13: run_13(B, m, x0, cc, out_one, out_final); break;
    case 17: run_17(B, m, x0, cc, out_one, out_final); break;
    case 23: run_23(B, m, x0, cc, out_one, out_final); break;
    case 36: run_36(B, m, x0, cc, out_one, out_final); break;
    case 45: run_45(B, m, x0, cc, out_one, out_final); break;
    case 64: run_64(B, m, x0, cc, out_one, out_final); break;
  }
}
void test_fft(long L, double *re, double *im, long s){
  switch(L){
    case 6: f6_p(re, im, s); break;
    case 8: f8_p(re, im, s); break;
    case 13: f13_p(re, im, s); break;
    case 17: f17_p(re, im, s); break;
    case 23: f23_p(re, im, s); break;
    case 36: f36_p(re, im, s); break;
    case 45: f45_p(re, im, s); break;
    case 64: f64_p(re, im, s); break;
  }
}
